import React, { useEffect, useState } from 'react';
import api from './api.ts';
import { userInfo } from 'os';
import logoclara from './img/logo-clara.png';
import logoescura from './img/logo-escura.png';
import logobranca from './img/logo-branca.png';

interface User {
  email: string;
  nome: string;
  role: 'admin' | 'licenciado';
}

interface Notice {
  id: number;
  message: string;
  created_at: string;
}

interface FileData {
  id: number;
  filename: string;
  originalname: string;
  uploaded_at: string;
}

const App: React.FC = () => {
  const [email, setEmail] = useState('');
  const [nome, setNome] = useState('');
  const [password, setPassword] = useState('');
  const [user, setUser] = useState<User | null>(null);
  const [notices, setNotices] = useState<Notice[]>([]);
  const [files, setFiles] = useState<FileData[]>([]);
  const [message, setMessage] = useState('');
  const [file, setFile] = useState<File | null>(null);

  const handleLogin = async () => {
    try {
      const res = await api.post('/api/login', { email, password });
      setUser(res.data);
    } catch (err) {
      alert('Revise os dados de login e tente novamente');
    }
  };

  const fetchData = async () => {
    const [nRes, fRes] = await Promise.all([
      api.get('/api/notices'),
      api.get('/api/files')
    ]);
    setNotices(nRes.data);
    setFiles(fRes.data);
  };

  const handlePostNotice = async () => {
    await api.post('/api/admin/notice', { message });
    setMessage('');
    fetchData();
  };

  const handleUpload = async () => {
    if (!file) return;
    const formData = new FormData();
    formData.append('file', file);
    await api.post('/api/admin/upload', formData, {
      headers: { 'Content-Type': 'multipart/form-data' },
    });
    setFile(null);
    fetchData();
  };

  useEffect(() => {
    if (user) fetchData();
  }, [user]);

  if (!user) { 
    return (
      <div>
        <div clas>
          <img alt="Logo da Valor Fiscal" src={logoclara}/>
        </div>
        <div className="p-1">

          <h2 className="titulo-login">Painel do Licenciado</h2>
          <input type="email" placeholder="Email" className="input-login" onChange={e => setEmail(e.target.value)} />
          <input type="password" placeholder="Senha" className="input-login" onChange={e => setPassword(e.target.value)} />
          <button className="botao-login" onClick={handleLogin}>Login</button>
          <p><a href="https://valorfiscal.com">Esqueceu sua senha?</a></p>
        </div>
      </div>
    );
  }

  return (
    <div className="p-2">
      <h2 className="titulo">Bem vindo!</h2>
      {user.role === 'admin' && (
        <div className="mb-6">
          <h3 className="text-lg font-semibold">Painel Administrativo</h3>
          <textarea className="input-comunicado" value={message} onChange={e => setMessage(e.target.value)} placeholder="Novo comunicado"></textarea>
          <button className="botao-comunicado" onClick={handlePostNotice}>Postar Comunicado</button>

          <input type="file" onChange={e => setFile(e.target.files?.[0] || null)} />
          <button className="botao-upload" onClick={handleUpload}>Publicar Arquivo</button>
        </div>
      )}

      <div className="mb-6">
        <h3 className="text-lg font-semibold">Comunicados</h3>
        <ul className="list-disc pl-6">
          {notices.map(n => (
            <li key={n.id}>{n.message} <span className="text-sm text-gray-500">({new Date(n.created_at).toLocaleString()})</span></li>
          ))}
        </ul>               
      </div>

      <div>
        <h3 className="text-lg font-semibold">Arquivos Disponíveis</h3>
        <ul className="list-disc pl-6">
          {files.map(f => (
            <li key={f.id}>
              <a href={`http://localhost:3001/uploads/${f.filename}`} target="_blank" rel="noreferrer" className="text-blue-600">
                {f.originalname}
              </a>
              <span className="text-sm text-gray-500"> ({new Date(f.uploaded_at).toLocaleString()})</span>
            </li>
          ))}
        </ul>
      </div>
    </div>
  );
};

export default App;
